from pathlib import Path

ROOT=Path(__file__).resolve().parents[2]

def read(path): return (ROOT/path).read_text(encoding='utf-8')
def write(path,text):
    p=ROOT/path; p.parent.mkdir(parents=True,exist_ok=True); p.write_text(text,encoding='utf-8')
def once(text,old,new,label):
    n=text.count(old)
    if n!=1: raise RuntimeError(f'{label}: expected exactly one match, got {n}')
    return text.replace(old,new,1)
def insert_after_line(text,line,new_line,label):
    old=line+'\n'
    if old not in text: raise RuntimeError(f'{label}: marker missing')
    if new_line+'\n' in text: return text
    return text.replace(old,old+new_line+'\n',1)

